-- 4. roles
CREATE ROLE ledger_owner NOLOGIN;
CREATE SCHEMA ledger AUTHORIZATION ledger_owner;
CREATE ROLE payments_app LOGIN PASSWORD :'app_password';
GRANT USAGE ON SCHEMA ledger TO payments_app;
ALTER DEFAULT PRIVILEGES FOR ROLE ledger_owner IN SCHEMA ledger
    GRANT SELECT, INSERT, UPDATE ON TABLES TO payments_app;
CREATE ROLE reports LOGIN PASSWORD :'reports_password';
GRANT pg_read_all_data TO reports;
GRANT payments_ops TO asha;                              -- a person, through a group role

-- 5. what can payments_app do on a table the owner created?
SET ROLE ledger_owner;
CREATE TABLE ledger.payouts (payout_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, amount_minor bigint NOT NULL);
RESET ROLE;
SELECT has_table_privilege('payments_app', 'ledger.payouts', 'INSERT') AS can_insert,   -- true
       has_table_privilege('payments_app', 'ledger.payouts', 'DELETE') AS can_delete;   -- false

