GRANT SELECT ON ALL TABLES IN SCHEMA ledger TO reports;        -- the tables that exist now
ALTER DEFAULT PRIVILEGES FOR ROLE ledger_owner IN SCHEMA ledger
    GRANT SELECT ON TABLES TO reports;                         -- the ones ledger_owner adds later

